307:     /// PakViewer LoadL1Image's natural-size RGBA8 reference output, including
308:     /// its RGB555-zero transparency. NOT generic native alpha or UI placement.
309:     /// Channels use bit replication; there is no grayscale-as-alpha heuristic.
310:     pub fn reference_rgba(&self) -> Result<Vec<u8>, IconError> {
311:         let mut rgba = allocated(self.rgb555.len() * 4, 0u8)?;
312:         for (index, &pixel) in self.rgb555.iter().enumerate() {
313:             if !self.coverage[index] || pixel == 0 {
314:                 continue;
315:             }
316:             let r = ((pixel >> 10) & 31) as u8;
317:             let g = ((pixel >> 5) & 31) as u8;
318:             let b = (pixel & 31) as u8;
319:             rgba[index * 4..index * 4 + 4].copy_from_slice(&[
320:                 (r << 3) | (r >> 2),
321:                 (g << 3) | (g >> 2),
322:                 (b << 3) | (b >> 2),
323:                 255,
324:             ]);
325:         }
326:         Ok(rgba)
327:     }
328: }
