334: pub fn decode_tbt_cancellable(bytes: &[u8], cancelled: &AtomicBool) -> Result<TbtImage, IconError> {
335:     check_cancelled(cancelled)?;
336:     if bytes.len() > MAX_TBT_BYTES {
337:         return Err(IconError::PayloadTooLarge {
338:             size: bytes.len() as u64,
339:             limit: MAX_TBT_BYTES,
340:         });
341:     }
342:     let header = bytes.get(..4).ok_or(IconError::Truncated)?;
343:     let height = usize::from(header[3]);
344:     let header_width = header[2];
345:     if header_width == 0 || height == 0 {
346:         return Err(IconError::EmptyImage);
347:     }
348:     let width = walk_rows(
349:         bytes,
350:         height,
351:         usize::from(header_width),
352:         cancelled,
353:         |_, _, _| {},
354:     )?;
355:     let pixels = width.checked_mul(height).ok_or(IconError::DimensionLimit)?;
356:     if pixels > MAX_TBT_PIXELS || height > MAX_TBT_HEIGHT {
357:         return Err(IconError::DimensionLimit);
358:     }
359:     check_cancelled(cancelled)?;
360:     let mut rgb555 = allocated(pixels, 0u16)?;
361:     let mut coverage = allocated(pixels, false)?;
362:     walk_rows(bytes, height, width, cancelled, |y, x, value| {
363:         rgb555[y * width + x] = value;
364:         coverage[y * width + x] = true;
365:     })?;
366:     check_cancelled(cancelled)?;
367:     Ok(TbtImage {
368:         offset: [header[0], header[1]],
369:         header_width,
370:         width,
371:         height,
372:         rgb555,
373:         coverage,
374:     })
375: }
