377: fn walk_rows(
378:     bytes: &[u8],
379:     height: usize,
380:     mut width: usize,
381:     cancelled: &AtomicBool,
382:     mut pixel: impl FnMut(usize, usize, u16),
383: ) -> Result<usize, IconError> {
384:     let mut cursor = 4;
385:     for y in 0..height {
386:         check_cancelled(cancelled)?;
387:         let spans = take_byte(bytes, &mut cursor)?;
388:         let mut x = 0usize;
389:         for _ in 0..spans {
390:             let skip = take_byte(bytes, &mut cursor)?;
391:             if skip & 1 != 0 {
392:                 return Err(IconError::OddByteSkip);
393:             }
394:             let count = usize::from(take_byte(bytes, &mut cursor)?);
395:             x = x
396:                 .checked_add(usize::from(skip / 2))
397:                 .ok_or(IconError::DimensionLimit)?;
398:             let end = x.checked_add(count).ok_or(IconError::DimensionLimit)?;
399:             if end > MAX_TBT_WIDTH {
400:                 return Err(IconError::DimensionLimit);
401:             }
402:             width = width.max(end);
403:             for column in x..end {
404:                 let lo = take_byte(bytes, &mut cursor)?;
405:                 let hi = take_byte(bytes, &mut cursor)?;
406:                 let value = u16::from_le_bytes([lo, hi]);
407:                 if value & 0x8000 != 0 {
408:                     return Err(IconError::UnsupportedPixelHighBit);
409:                 }
410:                 pixel(y, column, value);
411:             }
412:             x = end;
413:         }
414:     }
415:     if cursor != bytes.len() {
416:         return Err(IconError::TrailingBytes);
417:     }
418:     Ok(width)
419: }

